settings.sectionCSS:
.MRFJ3u p {
	color: [[${globalDesignMode ? 'var(--colorSecondary)' : colorSecondary}]];
	font-size: [[${globalDesignMode ? 'calc(var(--fontSizeBody) * 1px)' : fontSizeBody}]];
}

.MRFJ3u p + p {
	margin-top: 0.3125rem;
}

.MRFJ3u .MRFJ3u-list .embed-responsive {
	width: 9.375rem;
	margin-right: 0.9375rem;
}

.MRFJ3u .MRFJ3u-cover .media {
	padding-bottom: 1.375rem;
	border-bottom: [[${globalDesignMode ? 'calc(var(--borderWidth) * 1px)' : borderWidth + 'px'}]] [[${globalDesignMode ? 'var(--borderStyle)' : borderStyle}]] [[${globalDesignMode ? 'var(--colorBorder)' : colorBorder}]];
}

.MRFJ3u .MRFJ3u-cover .media .media-time {
	width: 6.25rem;
	height: 6.25rem;
	background-color: [[${globalDesignMode ? 'var(--colorTheme)' : colorTheme}]];
	display: flex;
	align-items: center;
	justify-content: center;
	margin-right: 0.9375rem;
}

.MRFJ3u .MRFJ3u-cover .media .media-time h5 {
	font-size: 2.25rem;
	line-height: 2.25rem;
	padding-bottom: 0.375rem;
	border-bottom: [[${globalDesignMode ? 'calc(var(--borderWidth) * 1px)' : borderWidth + 'px'}]] [[${globalDesignMode ? 'var(--borderStyle)' : borderStyle}]] [[${globalDesignMode ? 'var(--colorBorder)' : colorBorder}]];
}

.MRFJ3u .MRFJ3u-cover .media .media-time p, .MRFJ3u .MRFJ3u-cover .media .media-time h5 {
	color: #fff;
	text-align: center;
}

.MRFJ3u .MRFJ3u-cover .col-md-5 {
	padding-right: 1.875rem;
}

.MRFJ3u .MRFJ3u-cover li a {
	line-height: 2.25rem;
	color: [[${globalDesignMode ? 'var(--colorBody)' : colorBody}]];
	font-size: [[${globalDesignMode ? 'calc(var(--fontSizeContentHeading) * 1px)' : fontSizeContentHeading}]];
	font-family: [[${globalDesignMode ? 'var(--typeContentHeading)' : typeContentHeading}]];
	display: block;
	position: relative;
	padding-top: 0.625rem;
}

.MRFJ3u .MRFJ3u-cover li a h3 {
	padding-right: 1.875rem;
	margin-bottom: 0;
}

.MRFJ3u .MRFJ3u-cover li a:hover {
	color: [[${globalDesignMode ? 'var(--colorTheme)' : colorTheme}]];
}

.MRFJ3u .MRFJ3u-cover li:not(:last-child) {
	border-bottom: [[${globalDesignMode ? 'calc(var(--borderWidth) * 1px)' : borderWidth + 'px'}]] [[${globalDesignMode ? 'var(--borderStyle)' : borderStyle}]] [[${globalDesignMode ? 'var(--colorBorder)' : colorBorder}]];
}

.MRFJ3u .MRFJ3u-cover li:not(:last-child) a {
	padding-bottom: 1.25rem;
}

.MRFJ3u .MRFJ3u-cover [data-article-cover]:not(:first-child) {
	display: none;
}

.MRFJ3u .MRFJ3u-slick {
	position: relative;
}

.MRFJ3u .MRFJ3u-group {
	position: relative;
	width: 100%;
	left: 0;
	top: 0;
	opacity: 1;
}

.MRFJ3u .MRFJ3u-group:not(.active) {
	position: absolute;
	opacity: 0;
	z-index: 0;
}

.MRFJ3u .MRFJ3u-group.active {
	z-index: 1;
}

.MRFJ3u .nav-pills .nav-link {
	transition: all 0.25s;
}

.MRFJ3u .nav-pills .nav-link:hover:hover {
	background-color: [[${globalDesignMode ? 'var(--colorButtonHover)' : colorButtonHover}]];
	color: [[${globalDesignMode ? 'var(--colorButtonHoverLabel)' : colorButtonHoverLabel}]];
}

.MRFJ3u .slick-slider {
	margin-left: -15px;
	margin-right: -15px;
}

.MRFJ3u .slick-slider .slick-track {
	align-items: stretch;
	display: flex;
}

.MRFJ3u .slick-slider .slick-slide {
	margin-right: 15px;
	margin-left: 15px;
	padding-bottom: 15px;
}

@media (max-width: 768px) {
	.MRFJ3u .slick-slider {
		margin-left: -7.5px;
		margin-right: -7.5px;
	}

	.MRFJ3u .slick-slider .slick-slide {
		margin-right: 7.5px;
		margin-left: 7.5px;
	}
}

@media (max-width: 768px) {
	.MRFJ3u .MRFJ3u-cover .col-md-5 {
		padding-right: 0.46875rem;
	}
}
